import numpy as np

def generate(params, n, chip):
    w_s = max(2, min(int(params['spine_width']), 6))
    w_f = max(2, min(int(params['fin_width']), 6))
    l_f = max(2, min(int(params['fin_length']), 25))
    n_t = max(2, min(int(params['num_turns']), 10))
    t_s = max(2, min(int(params['turn_spacing']), 10))

    design = np.zeros((n, n), dtype=bool)
    i0, i1, j0, j1 = chip
    design[i0:i1+1, j0:j1+1] = True
    ci, cj = (i0 + i1) // 2, (j0 + j1) // 2

    half_s = w_s // 2
    spine_len = n_t * (w_s + t_s)
    start_i = ci - spine_len // 2
    end_i = start_i + spine_len

    for i in range(start_i, end_i):
        if 0 <= i < n:
            for di in range(-half_s, half_s + 1):
                ni = i + di
                if 0 <= ni < n:
                    design[ni, cj] = True

    for turn in range(n_t):
        y = cj + (turn + 1) * (w_s + t_s)
        for dy in range(-w_f//2, w_f//2 + 1):
            ny = y + dy
            if 0 <= ny < n:
                for i in range(start_i, min(end_i, n)):
                    for dx in range(l_f):
                        nx = i + dx
                        if 0 <= nx < n:
                            design[nx, ny] = True
                for i in range(max(start_i, 0), end_i):
                    for dx in range(l_f):
                        nx = i - dx
                        if 0 <= nx < n:
                            design[nx, ny] = True

    chip_mask = np.zeros((n, n), dtype=bool)
    chip_mask[i0:i1+1, j0:j1+1] = True
    visited = chip_mask.copy()
    frontier = list(zip(*np.where(chip_mask)))

    while frontier:
        i, j = frontier.pop(0)
        for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < n and not visited[ni, nj]:
                visited[ni, nj] = True
                frontier.append((ni, nj))

    design &= visited

    kernel = np.array([[1,1],[1,1]], dtype=bool)
    eroded = np.zeros_like(design)
    for i in range(n-1):
        for j in range(n-1):
            if design[i:i+2, j:j+2].all():
                eroded[i:i+2, j:j+2] = True
    design = eroded

    def fill_holes(mask):
        filled = mask.copy()
        changed = True
        while changed:
            changed = False
            for i in range(1, n-1):
                for j in range(1, n-1):
                    if not filled[i,j]:
                        if filled[i-1,j] and filled[i+1,j] and filled[i,j-1] and filled[i,j+1]:
                            filled[i,j] = True
                            changed = True
        return filled

    design = fill_holes(design)

    chip_mask = np.zeros((n, n), dtype=bool)
    chip_mask[i0:i1+1, j0:j1+1] = True
    visited = chip_mask.copy()
    frontier = list(zip(*np.where(chip_mask)))

    while frontier:
        i, j = frontier.pop(0)
        for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < n and not visited[ni, nj]:
                visited[ni, nj] = True
                frontier.append((ni, nj))

    design &= visited

    max_cells = 1440
    if design.sum() > max_cells:
        dist = np.full((n, n), np.inf)
        q = []
        for i in range(i0, i1+1):
            for j in range(j0, j1+1):
                dist[i, j] = 0
                q.append((i, j))
        h = 0
        while h < len(q):
            i, j = q[h]
            h += 1
            for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < n and dist[ni, nj] == np.inf:
                    dist[ni, nj] = dist[i, j] + 1
                    q.append((ni, nj))
        flat_idx = np.argsort(dist, axis=None)[:max_cells]
        new_design = np.zeros_like(design)
        new_design.flat[flat_idx] = True
        design = new_design

        visited = chip_mask.copy()
        frontier = list(zip(*np.where(chip_mask)))
        while frontier:
            i, j = frontier.pop(0)
            for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < n and not visited[ni, nj] and design[ni, nj]:
                    visited[ni, nj] = True
                    frontier.append((ni, nj))
        design &= visited

    return design
